def min_blow_to_defeat_zmei(t):
    results = []

    for _ in range(t):
        n, x = map(int, input().split())
        blows = []

        for _ in range(n):
            d, h = map(int, input().split())
            blows.append((d, h))

        blows.sort(key=lambda b: (b[0] - b[1], b[0]))

        total_blow = 0
        while x > 0:
            found = False
            for d, h in blows:
                if d <= x:
                    x -= d
                    x += h
                    total_blow += 1
                    found = True
                    break

            if not found:
                results.append(-1)
                break

        else:
            results.append(total_blow)

    for result in results:
        print(result)

